package com.bplus.share;
import org.json.*;import java.util.*;import java.util.concurrent.*;
/** Persistent text outbox. Network attempts occur only while app foreground service is alive. */
public final class Outbox {
 private static ScheduledExecutorService timer;private static final Map<String,Long> due=new ConcurrentHashMap<>();private static final Map<String,Integer> failures=new HashMap<>();
 public static synchronized void start(){if(timer!=null)return;timer=Executors.newSingleThreadScheduledExecutor();timer.scheduleWithFixedDelay(()->sweep(),0,5,TimeUnit.SECONDS);}
 public static synchronized void stop(){if(timer!=null)timer.shutdownNow();timer=null;}
 public static void kick(){start();}
 public static JSONObject enqueue(String peer,String text)throws Exception{if(Store.peerById(peer)==null||text.isEmpty()||text.length()>8000)throw new java.io.IOException("Invalid queued message");JSONObject m=new JSONObject().put("id",UUID.randomUUID().toString()).put("wireId",Recall.secret()).put("recallKey",Recall.secret()).put("kind","text").put("body",text).put("me",true).put("ts",System.currentTimeMillis()).put("state","queued");synchronized(Store.class){if(Store.peerById(peer)==null)throw new java.io.IOException("Device no longer paired");JSONArray t=Store.thread(peer);t.put(m);Store.durable("thread_"+peer,t.toString());}TransferService.changed(peer);synchronized(due){due.remove(peer);}kick();return m;}
 static boolean pending(JSONObject m){String s=m.optString("state");return m.optBoolean("me")&&m.optString("kind").equals("text")&&Recall.valid(m.optString("wireId"))&&Recall.valid(m.optString("recallKey"))&&(s.equals("queued")||s.equals("sending")||s.equals("failed"));}
 static void state(String peer,String wire,String state,String error)throws Exception{synchronized(Store.class){JSONArray t=Store.thread(peer);boolean changed=false;for(int i=0;i<t.length();i++){JSONObject m=t.optJSONObject(i);if(m!=null&&m.optBoolean("me")&&wire.equals(m.optString("wireId"))&&!m.optString("state").equals("canceled")){if(m.optString("state").equals("read")&&!state.equals("read"))continue;if(!m.optString("state").equals(state)||!m.optString("error").equals(error)){m.put("state",state).put("error",error);changed=true;}}}if(changed){Store.durable("thread_"+peer,t.toString());TransferService.changed(peer);}}}
 static void sweep(){JSONArray peers=Store.peers();for(int i=0;i<peers.length();i++){JSONObject p=peers.optJSONObject(i);if(p==null||Thread.currentThread().isInterrupted())return;String id=p.optString("id");if(System.currentTimeMillis()<due.getOrDefault(id,0L))continue;try{JSONObject hello=LanSync.call(p,new JSONObject().put("op","hello"));JSONArray caps=hello.optJSONArray("capabilities");if(caps==null||!caps.toString().contains("\"durable-text\""))throw new java.io.IOException("Peer upgrade required");JSONArray thread=Store.thread(id);for(int j=0;j<thread.length();j++){JSONObject m=thread.optJSONObject(j);if(m==null||!pending(m))continue;JSONObject live=Store.peerById(id);if(live==null)break;boolean stillPending=false;JSONArray latest=Store.thread(id);for(int k=0;k<latest.length();k++){JSONObject q=latest.optJSONObject(k);if(q!=null&&m.optString("wireId").equals(q.optString("wireId"))&&pending(q))stillPending=true;}if(!stillPending)continue;String wire=m.optString("wireId");state(id,wire,"queued","");JSONObject reply=LanSync.call(live,new JSONObject().put("op","send").put("wire",wire).put("key",m.optString("recallKey")).put("text",m.optString("body")));if(!wire.equals(reply.optString("wire")))throw new java.io.IOException("Wrong acknowledgement");String status=reply.optString("status");if(status.equals("delivered")||status.equals("read")||status.equals("deleted"))state(id,wire,status.equals("deleted")?"delivered":status,"");else throw new java.io.IOException("Invalid acknowledgement");}
 JSONArray batch=new JSONArray();thread=Store.thread(id);for(int j=thread.length()-1;j>=0&&batch.length()<100;j--){JSONObject m=thread.optJSONObject(j);if(m!=null&&m.optBoolean("me")&&(m.optString("state").equals("sent")||m.optString("state").equals("delivered"))&&Recall.valid(m.optString("wireId"))&&Recall.valid(m.optString("recallKey")))batch.put(new JSONObject().put("wire",m.optString("wireId")).put("key",m.optString("recallKey")));}if(batch.length()>0&&Store.peerById(id)!=null){JSONArray receipts=LanSync.call(p,new JSONObject().put("op","status").put("items",batch)).getJSONArray("items");for(int j=0;j<receipts.length();j++){JSONObject receipt=receipts.getJSONObject(j);String status=receipt.optString("status");if(status.equals("delivered")||status.equals("read"))state(id,receipt.optString("wire"),status,"");}}failures.remove(id);due.put(id,System.currentTimeMillis()+10000);
 }catch(Exception e){int n=Math.min(5,failures.getOrDefault(id,0)+1);failures.put(id,n);due.put(id,System.currentTimeMillis()+Math.min(60000,2000L*(1L<<n)));}}
 }
}
